void liveSaveRecovery(const wchar_t* root,const wchar_t* map){
    wchar_t userDir[32768];if(!GetEnvironmentVariableW(L"MEGINE_WAR3_USER_DIR",userDir,32768))throw std::runtime_error("Set an isolated MEGINE_WAR3_USER_DIR before this test");auto make=[&](bool start){Archives archives(root);archives.mountMap(map);auto world=World::read(archives);auto info=world->data().info;auto session=std::make_unique<ScriptSession>(jass::Module::compile(jass::Program::read(archives)),info,MapStrings{},std::optional<unsigned>{},std::optional<std::uint32_t>{0x69707365u});session->attachWorld(std::move(world));session->audioMuted(true);session->audioSimulationClock();session->configure();PlayerSetup setup(info,session->config());if(!setup.control(1,SlotControl::ComputerNormal) || !setup.race(1,1))throw std::runtime_error("Unable to set computer player");session->applySetup(setup);if(start)session->startMain();return session;};auto original=make(true);original->advance(60);if(!original->ais()[1])throw std::runtime_error("Original AI missing");auto units=original->units().size();auto gold=original->config().players[1].states.at(1);auto threads=original->ais()[1]->runtime->threadCount();original->saveLocalGame("ai-live.w3z");auto restored=make(false);auto info=ScriptSession::inspectRecoveryCheckpoint(root,"ai-live.w3z");restored->restoreRecoveryCheckpoint("ai-live.w3z",info.fileDigest);restored->notifyGameLoaded();restored->activateRecoveredSession();if(!restored->ais()[1] || restored->units().size()!=units || restored->config().players[1].states.at(1)!=gold || restored->ais()[1]->runtime->threadCount()!=threads)throw std::runtime_error("Live AI state changed during recovery");for(int n=0;n<8;++n){original->advance(30);restored->advance(30);}auto summary=[](const ScriptSession& session){std::map<std::uint32_t,unsigned> types;unsigned queues=0;for(auto& [id,u]:session.units())if(u->owner==1 && std::bit_cast<float>(u->life.bits())>0){++types[u->type];queues+=unsigned(u->production.size());}return std::pair{types,queues};};if(!restored->ais()[1]->runtime->threadCount() || restored->simulationTime()<300 || restored->config().players[1].states.at(1)==gold || summary(*restored)!=summary(*original) || restored->config().players[1].states!=original->config().players[1].states)throw std::runtime_error("Restored AI diverged during continuation");if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"PASS live_ai_disk_recovery elapsed="<<restored->simulationTime()<<" units="<<units<<" threads="<<threads<<"\nRESULT passed=1 failed=0 game_dll_loaded=false\n";
}
